input.command:
mkdir bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type    = string
  default = "eu-north-1"
}
EOF
cat > main.tf <<'EOF'
data "aws_caller_identity" "current" {}

locals {
  bucket_name = "reports-tfstate-${data.aws_caller_identity.current.account_id}-${var.region}"
}

resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

# State holds the uploader's secret access key, so encrypt it at rest.
resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "state_region" {
  value = var.region
}
EOF
cd ..
cat > backend.tf <<'EOF'
# The bucket is created by bootstrap/. Its name is passed at init time:
#   terraform init -backend-config="bucket=<bootstrap output state_bucket>"
terraform {
  backend "s3" {
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
cat > README.md <<'EOF'
# reports

Terraform for the reports bucket and the key the nightly export job uploads with. The job reads
the key from `terraform output`.

## Remote state

State lives in a versioned, encrypted, private S3 bucket with native S3 locking
(`use_lockfile`, needs Terraform >= 1.10), so anyone with access can run `plan` and `apply`;
concurrent runs are blocked by the lock. The state contains the uploader's secret access key, so
grant bucket access (`s3:ListBucket`, `s3:GetObject`, `s3:PutObject`, `s3:DeleteObject` on
`reports/*`) only to people who may read that key.

### One-time bootstrap (one person)

`bootstrap/` creates the state bucket. It uses local state (it can't store state in a bucket that
doesn't exist yet); it's small and rarely changes, so keep its `terraform.tfstate` safe or
re-import the bucket if it is lost.

```sh
cd bootstrap
terraform init
terraform apply
terraform output -raw state_bucket
```

### Migrating the existing local state (once, by whoever holds `terraform.tfstate`)

```sh
terraform init -migrate-state -backend-config="bucket=<state_bucket>"
```

Answer `yes` to copy the state, then confirm with `terraform plan` (expect no changes) and delete
the local `terraform.tfstate*` files.

### Everyday workflow (everyone)

```sh
terraform init -backend-config="bucket=<state_bucket>"
terraform plan
terraform apply
```

Never commit state files; `.gitignore` excludes them. If a run is killed and leaves a stale lock,
use `terraform force-unlock <id>` only after confirming nobody else is running.
